import { auth, signOut } from "@/auth";
import Link from "next/link";

export default async function Navigation() {
  const session = await auth();

  const links = [
    { name: 'Home', path: '/' },
    { name: 'Categories', path: '/categories' },
    { name: 'Connected Services', path: '/connected-services' },
    { name: 'Wishlist', path: '/wishlist' },
    { name: 'History', path: '/history' },
  ];

  return (
    <header className="header-nav" style={{flexWrap: 'wrap', gap: '1rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
      <div style={{display: 'flex', alignItems: 'center', gap: '2rem'}}>
        <Link href="/" className="logo" style={{fontWeight: 'bold', fontSize: '1.5rem', color: 'var(--primary)', textDecoration: 'none'}}>
          CompareAll
        </Link>
        <nav className="header-links" style={{display: 'flex', gap: '1rem', flexWrap: 'wrap', fontSize: '0.875rem'}}>
          {links.map(link => (
            <Link key={link.name} href={link.path} style={{color: 'var(--muted)', textDecoration: 'none'}}>
              {link.name}
            </Link>
          ))}
        </nav>
      </div>

      <div style={{display: 'flex', alignItems: 'center', gap: '1rem'}}>
        {session?.user ? (
          <div style={{display: 'flex', alignItems: 'center', gap: '1rem'}}>
            <div style={{display: 'flex', alignItems: 'center', gap: '0.5rem'}}>
              {session.user.image && (
                <img src={session.user.image} alt="Profile" style={{width: '32px', height: '32px', borderRadius: '50%'}} />
              )}
              <span style={{fontSize: '0.875rem', fontWeight: '500'}}>{session.user.name}</span>
            </div>
            <form action={async () => {
              "use server";
              await signOut();
            }}>
              <button type="submit" style={{padding: '0.4rem 0.8rem', fontSize: '0.875rem', color: 'white', background: 'var(--foreground)', borderRadius: '6px', border: 'none', cursor: 'pointer'}}>
                Logout
              </button>
            </form>
          </div>
        ) : (
          <Link href="/login" style={{padding: '0.5rem 1rem', fontSize: '0.875rem', color: 'white', background: 'var(--primary)', borderRadius: '6px', textDecoration: 'none', fontWeight: 'bold'}}>
            Login / Sign up
          </Link>
        )}
      </div>
    </header>
  );
}

